class Page_ActionPoppedOut_ProxyToResponder : public ::mojo::internal::ProxyToResponder {
 public:
  static Page::ActionPoppedOutCallback CreateCallback(
      ::mojo::Message& message,
      std::unique_ptr<mojo::internal::ResponderThunk>&& responder) {
    std::unique_ptr<Page_ActionPoppedOut_ProxyToResponder> proxy(
        new Page_ActionPoppedOut_ProxyToResponder(
            message, std::move(responder)));
    return base::BindOnce(&Page_ActionPoppedOut_ProxyToResponder::Run,
                          std::move(proxy));
  }

  ~Page_ActionPoppedOut_ProxyToResponder() {
#if DCHECK_IS_ON()
    if (responder_) {
      // If we're being destroyed without being run, we want to ensure the
      // binding endpoint has been closed. This checks for that asynchronously.
      // We pass a bound generated callback to handle the response so that any
      // resulting DCHECK stack will have useful interface type information.
      // Instantiate a ScopedFizzleBlockShutdownTasks to allow this request to
      // fizzle if this happens after shutdown and the endpoint is bound to a
      // BLOCK_SHUTDOWN sequence.
      base::ThreadPoolInstance::ScopedFizzleBlockShutdownTasks fizzler;
      responder_->IsConnectedAsync(base::BindOnce(&OnIsConnectedComplete));
    }
#endif
  }

 private:
  Page_ActionPoppedOut_ProxyToResponder(
      ::mojo::Message& message,
      std::unique_ptr<mojo::internal::ResponderThunk>&& responder)
      : ::mojo::internal::ProxyToResponder(message, std::move(responder)) {
  }

#if DCHECK_IS_ON()
  static void OnIsConnectedComplete(bool connected) {
    DCHECK(!connected)
        << "Page::ActionPoppedOutCallback was destroyed without "
        << "first either being run or its corresponding binding being closed. "
        << "It is an error to drop response callbacks which still correspond "
        << "to an open interface pipe.";
  }
#endif

  void Run(
      );
};

bool Page_ActionPoppedOut_ForwardToCallback::Accept(
    mojo::Message* message) {
  DCHECK(message->is_serialized());
  internal::Page_ActionPoppedOut_ResponseParams_Data* params =
      reinterpret_cast<
          internal::Page_ActionPoppedOut_ResponseParams_Data*>(
              message->mutable_payload());
  

  // Validation for Page.2
  bool success = true;
  Page_ActionPoppedOut_ResponseParamsDataView input_data_view(params, message);
  
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        Page::Name_, 2, true);
    return false;
  }
  if (!callback_.is_null()) {
    std::move(callback_).Run();
  }
  return true;
}

void Page_ActionPoppedOut_ProxyToResponder::Run(
    ) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT0("mojom", "Send reply extensions_bar::mojom::Page::ActionPoppedOut");
#endif

  const uint32_t kFlags = mojo::Message::kFlagIsResponse |
      ((is_sync_) ? mojo::Message::kFlagIsSync : 0) |
      ((true) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((false) ? mojo::Message::kFlagIsUrgent : 0);

  const size_t estimated_payload_size =
    0;
  mojo::Message message(
      std::to_underlying(messages::Page::kActionPoppedOut), kFlags, estimated_payload_size);
  mojo::internal::MessageFragment<
      ::extensions_bar::mojom::internal::Page_ActionPoppedOut_ResponseParams_Data> params(
          message);
  params.Allocate();

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(Page::Name_);
  message.set_method_name("ActionPoppedOut");
#endif

  message.set_request_id(request_id_);
  message.set_trace_nonce(trace_nonce_);
  ::mojo::internal::SendMojoMessage(*responder_, message);
  // SendMojoMessage() fails silently if the responder connection is closed,
  // or if the message is malformed.
  //
  // TODO(darin): If Accept() returns false due to a malformed message, that
  // may be good reason to close the connection. However, we don't have a
  // way to do that from here. We should add a way.
  responder_ = nullptr;
}

// static
bool PageStubDispatch::Accept(
    Page* impl,
    mojo::Message* message) {
  switch (static_cast<messages::Page>(message->header()->name)) {
    case messages::Page::kActionsAddedOrUpdated: {
      DCHECK(message->is_serialized());
      internal::Page_ActionsAddedOrUpdated_Params_Data* params =
          reinterpret_cast<internal::Page_ActionsAddedOrUpdated_Params_Data*>(
              message->mutable_payload());
      

      // Validation for Page.0
      bool success = true;
      std::vector<::toolbar_ui_api::mojom::IconUpdatePtr> p_icons{};
      std::vector<::extensions_bar::mojom::ExtensionActionInfoPtr> p_actions{};
      Page_ActionsAddedOrUpdated_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadIcons(&p_icons))
        success = false;
      if (success && !input_data_view.ReadActions(&p_actions))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->ActionsAddedOrUpdated(        
        std::move(p_icons), 
        std::move(p_actions));
      return true;
    }
    case messages::Page::kActionRemoved: {
      DCHECK(message->is_serialized());
      internal::Page_ActionRemoved_Params_Data* params =
          reinterpret_cast<internal::Page_ActionRemoved_Params_Data*>(
              message->mutable_payload());
      

      // Validation for Page.1
      bool success = true;
      std::vector<::toolbar_ui_api::mojom::IconUpdatePtr> p_icons{};
      std::string p_id{};
      Page_ActionRemoved_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadIcons(&p_icons))
        success = false;
      if (success && !input_data_view.ReadId(&p_id))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->ActionRemoved(        
        std::move(p_icons), 
        std::move(p_id));
      return true;
    }
    case messages::Page::kActionPoppedOut: {
      break;
    }
  }
  return false;
}

// static
bool PageStubDispatch::AcceptWithResponder(
    Page* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::internal::ResponderThunk> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (static_cast<messages::Page>(message->header()->name)) {
    case messages::Page::kActionsAddedOrUpdated: {
      break;
    }
    case messages::Page::kActionRemoved: {
      break;
    }
    case messages::Page::kActionPoppedOut: {
      internal::Page_ActionPoppedOut_Params_Data* params =
          reinterpret_cast<
              internal::Page_ActionPoppedOut_Params_Data*>(
                  message->mutable_payload());
      

      // Validation for Page.2
      bool success = true;
      Page_ActionPoppedOut_ParamsDataView input_data_view(params, message);
      
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 2, false);
        return false;
      }
      auto callback =
          Page_ActionPoppedOut_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->ActionPoppedOut(std::move(callback));
      return true;
    }
  }
  return false;
}
